    const reserved = step("reserve", () => {
      const body = requestJson(req);
      return { orderId: body.orderId, status: "reserved" };
    });
    const charged = step("charge", () => {
      return { orderId: reserved.orderId, status: "charged" };
    });
    return Response.json({ reserved: reserved, charged: charged });
  });
}
